import type {
  MainNavUserProps,
  MainNavUserAvatarProps,
  MainNavUserNotificationsProps,
} from "../main-nav.types";

import React, { forwardRef, Children, isValidElement } from "react";
import { clsx } from "clsx";
import { Float } from "@components/float";

import { useMainNav } from "../hooks/use-main-nav";
import { MainNavClasses } from "../main-nav.styles";

import { MainNavItem } from "./main-nav-items";

export const MainNavUserAvatar: React.FC<MainNavUserAvatarProps> = ({ children }) => {
  return <>{children}</>;
};
MainNavUserAvatar.displayName = "MainNav.UserAvatar";

export const MainNavUserNotifications: React.FC<MainNavUserNotificationsProps> = ({ children }) => {
  return <>{children}</>;
};
MainNavUserNotifications.displayName = "MainNav.UserNotifications";

const MainNavUserInner = (
  { className, children, ...props }: MainNavUserProps<"button">,
  ref: React.ForwardedRef<HTMLButtonElement>,
) => {
  const { collapsed, theme } = useMainNav();

  let avatarElement: React.ReactElement | null = null;
  let avatarName: string | null = null;
  let notificationElement: React.ReactElement | null = null;
  const otherChildren: React.ReactNode[] = [];

  Children.forEach(children, (child) => {
    if (isValidElement(child)) {
      if (child.type === MainNavUserAvatar) {
        avatarElement = Children.only(child.props.children) as React.ReactElement;
        avatarName = child.props.name || avatarElement.props.name || null;
      } else if (child.type === MainNavUserNotifications) {
        notificationElement = Children.only(child.props.children) as React.ReactElement;
      } else {
        otherChildren.push(child);
      }
    } else {
      otherChildren.push(child);
    }
  });

  const notificationOffset = theme.toPx("0.143rem");
  const userContent = (
    <>
      {avatarElement && notificationElement ? (
        <Float offSetX={notificationOffset} offSetY={notificationOffset}>
          <Float.Anchor>{avatarElement}</Float.Anchor>
          <Float.Content>{notificationElement}</Float.Content>
        </Float>
      ) : avatarElement ? (
        avatarElement
      ) : null}
      {otherChildren}
    </>
  );

  return (
    <MainNavItem
      ref={ref}
      className={clsx(MainNavClasses.user, className)}
      // get name from Avatar component
      customTooltip={avatarName}
      data-main-nav-state={collapsed ? "collapsed" : "expanded"}
      {...props}
    >
      {userContent}
    </MainNavItem>
  );
};
export const MainNavUser = React.memo(forwardRef(MainNavUserInner));
MainNavUser.displayName = "MainNav.User";
